+++ b/pkg/store/store.go
@@ -0,0 +1,25 @@
+package store
+
+import "sync"
+
+type Store struct {
+	mu   sync.RWMutex
+	data map[string]int
+}
+
+func New() *Store {
+	return &Store{data: make(map[string]int)}
+}
+
+func (s *Store) Set(key string, val int) {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	s.data[key] = val
+}
+
+func (s *Store) Get(key string) (int, bool) {
+	s.mu.RLock()
+	defer s.mu.RUnlock()
+	v, ok := s.data[key]
+	return v, ok
+}
